<?php
namespace App\Support;
final class EnvWriter {/** @param array<string,string|int|bool|null> $values */public function write(string $path,array $values):void{$content=file_exists($path)?(string)file_get_contents($path):'';foreach($values as $key=>$value){$encoded=$this->encode($value);$pattern='/^'.preg_quote($key,'/').'=.*$/m';$line=$key.'='.$encoded;if(preg_match($pattern,$content))$content=preg_replace($pattern,$line,$content)??$content;else$content.=($content!==''&&!str_ends_with($content,"\n")?"\n":'').$line."\n";}if(file_put_contents($path,$content,LOCK_EX)===false)throw new \RuntimeException('Unable to write environment file.');}private function encode(mixed $value):string{if($value===null)return 'null';if(is_bool($value))return $value?'true':'false';$str=(string)$value;if($str===''||preg_match('/\s|#|"|\'|=/', $str))return '"'.str_replace(['\\','"'],['\\\\','\\"'],$str).'"';return $str;}}
